-- 조직도 데이터 — HRM(인사평가) 로컬 DB 의 부서 관리·사용자 관리 설정을 CRM 으로 옮긴다 (2026-10-06 생성, 사용자 요청).
-- 담는 것: 부서 — 상위 부서·부서장·사용 여부·표시 순서, 직접 추가 부서(이름으로 찾고 없으면 만든다)
--          사용자 — 직책·상태 (역할은 옮기지 않는다 — CRM 역할 체계 그대로. admin 계정 제외)
-- 사람 = 사번, ERP 부서 = 부서 코드, 직접 추가 부서 = 이름으로 맞춘다. CRM 에만 있는 부서·사용자는 건드리지 않는다.
-- ERP 부서는 INSERT … ON DUPLICATE KEY UPDATE — ERP 동기화 전의 빈 DB(운영 첫 기동)에서도 트리가 만들어지고,
-- 이후 동기화가 이름·비용센터를 채운다(상위 부서는 ERP 에 값이 있을 때만 덮어쓴다). 사용자 줄은 그 사람이 CRM 에 있을 때만 적용된다.

-- 1) 직접 추가 부서 2개 — 같은 이름이 없으면 만든다(번호는 90001~ 빈 다음 번호)
INSERT INTO departments (company_cd, dept_cd, dept_nm, erp_dept_code, use_yn, created_at, updated_at, created_id, updated_id)
SELECT 1000, COALESCE(MAX(CASE WHEN dept_cd >= 90001 THEN dept_cd END), 90000) + 1, '그래픽스사업본부', NULL, 'Y', NOW(), NOW(), 'system', 'system'
  FROM departments WHERE company_cd = 1000
HAVING COALESCE(SUM(dept_nm = '그래픽스사업본부' AND erp_dept_code IS NULL), 0) = 0;
INSERT INTO departments (company_cd, dept_cd, dept_nm, erp_dept_code, use_yn, created_at, updated_at, created_id, updated_id)
SELECT 1000, COALESCE(MAX(CASE WHEN dept_cd >= 90001 THEN dept_cd END), 90000) + 1, '타라티피에스', NULL, 'Y', NOW(), NOW(), 'system', 'system'
  FROM departments WHERE company_cd = 1000
HAVING COALESCE(SUM(dept_nm = '타라티피에스' AND erp_dept_code IS NULL), 0) = 0;
SET @m1 := (SELECT MIN(dept_cd) FROM departments WHERE company_cd = 1000 AND erp_dept_code IS NULL AND dept_nm = '그래픽스사업본부'); -- 그래픽스사업본부
SET @m2 := (SELECT MIN(dept_cd) FROM departments WHERE company_cd = 1000 AND erp_dept_code IS NULL AND dept_nm = '타라티피에스'); -- 타라티피에스

-- 2) 직접 추가 부서 설정
UPDATE departments SET up_dept_cd = NULL, head_employee_no = '10011471', use_yn = 'Y', sort_order = 30, updated_at = NOW(), updated_id = 'system' WHERE company_cd = 1000 AND dept_cd = @m1;
UPDATE departments SET up_dept_cd = NULL, head_employee_no = NULL, use_yn = 'Y', sort_order = 10, updated_at = NOW(), updated_id = 'system' WHERE company_cd = 1000 AND dept_cd = @m2;

-- 3) ERP 부서 99개 — 상위 부서·부서장·사용 여부·순서 (없으면 만든다)
